(() => {
'use strict';
const paths={leaf:'M19 4C9 3 3 8 5 15c7 5 14-1 14-11ZM5 20l10-11',sickle:'M20 4C13 3 6 7 5 14c0 3 1 5 4 6M9 20l3-4m0 0 2 2m-2-2 5-5',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM16 8l-3 5-5 3 3-5 5-3Z',chart:'M4 4v16h16M7 15l4-5 4 3 5-7',book:'M12 6c-3-2-7-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Zm0 0v14',download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',edit:'m4 15 11-11 5 5-11 11H4v-5Zm9-9 5 5',sliders:'M4 7h16M4 17h16M8 4v6m8 4v6',compare:'M4 5h6v14H4V5Zm10 0h6v14h-6V5Z',save:'M6 3h12v18l-6-4-6 4V3Z',print:'M7 8V3h10v5M7 17H3V9h18v8h-4M7 14h10v7H7v-7',reset:'M4 9a8 8 0 1 1 1 9M4 3v6h6',check:'m5 12 4 4L19 6',plus:'M12 4v16M4 12h16',next:'m9 5 7 7-7 7',pin:'M12 21s7-7 7-12a7 7 0 1 0-14 0c0 5 7 12 7 12Zm0-15a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z'};
function icon(name){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.6');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');svg.classList.add('action-icon');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',paths[name]||paths.compass);svg.append(path);return svg;}
function pick(el){const text=el.textContent.toLowerCase(),d=el.dataset;if(d.save||text.includes('save plan')||text.includes('save this'))return 'save';if(d.compare||text.includes('compare'))return 'compare';if(text.includes('export'))return 'download';if(text.includes('print'))return 'print';if(text.includes('edit'))return 'edit';if(text.includes('reset')||text.includes('restore'))return 'reset';if(text.includes('methodology')||text.includes('official')||text.includes('understand')||text.includes('explanation'))return 'book';if(text.includes('scenario')||text.includes('what-if')||text.includes('priorit'))return 'sliders';if(text.includes('save field'))return 'check';if(text.includes('profile')||text.includes('field setup'))return 'pin';if(text.includes('pattern')||text.includes('climate'))return 'chart';if(text.includes('start')||text.includes('grow'))return 'leaf';if(text.includes('continue'))return 'next';if(text.includes('add'))return 'plus';return 'compass';}
function decorate(root=document){root.querySelectorAll('button,a').forEach(el=>{if(el.querySelector('.action-icon'))return;const nodes=[];const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);while(walker.nextNode())if(/[↗]/.test(walker.currentNode.nodeValue))nodes.push(walker.currentNode);if(!nodes.length){if(el.matches('.shell button.primary,.shell .actions button,.shell button[data-action=export]')){el.append(icon(pick(el)));}return;}const name=pick(el);nodes.forEach(n=>{const text=n.nodeValue;const parts=text.split('↗');const fragment=document.createDocumentFragment();parts.forEach((p,i)=>{fragment.append(document.createTextNode(p));if(i<parts.length-1)fragment.append(icon(name));});n.replaceWith(fragment);});});}
decorate();
if ('IntersectionObserver' in window) {
 const motionObserver = new IntersectionObserver(entries => entries.forEach(entry => entry.target.classList.toggle('motion-in-view', entry.isIntersecting)), {rootMargin:'50px'});
 document.querySelectorAll('.journey-item,.evidence-atlas,.closing-landscape').forEach(el => motionObserver.observe(el));
} else document.querySelectorAll('.journey-item,.evidence-atlas,.closing-landscape').forEach(el => el.classList.add('motion-in-view'));
const main=document.getElementById('main');if(main)new MutationObserver(()=>decorate(main)).observe(main,{childList:true,subtree:true});const dialog=document.getElementById('details');if(dialog)new MutationObserver(()=>decorate(dialog)).observe(dialog,{childList:true,subtree:true});
const layers={rain:['01','Look for patterns, not promises.','Regional rainfall history adds context to water decisions. This visualization uses no live observations.'],soil:['02','Your soil tells its own story.','Texture, drainage, and measured pH help narrow feasible options. Unknown measurements should remain explicit.'],crop:['03','Connect one season to the next.','Crop families, planting windows, and rotation trade-offs connect field context to an explainable plan.']};
function layer(button){document.querySelectorAll('[data-layer]').forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1;});const [number,heading,description]=layers[button.dataset.layer],panel=document.getElementById('atlas-readout');panel.setAttribute('aria-labelledby',button.id);panel.innerHTML=`<span class="layer-number">${number}</span><div><b>${heading}</b><p>${description}</p></div>`;document.querySelector('.evidence-atlas').dataset.layer=button.dataset.layer;}
document.querySelectorAll('[data-layer]').forEach(b=>{b.addEventListener('click',()=>layer(b));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...document.querySelectorAll('[data-layer]')];let idx=buttons.indexOf(b);idx=e.key==='Home'?0:e.key==='End'?2:(idx+(e.key==='ArrowRight'?1:2))%3;buttons[idx].focus();layer(buttons[idx]);});});
// Native 40px sickle cursor; no pointer-following or click effects.
const style=document.createElement('style');style.textContent=`@media (hover:hover) and (pointer:fine){html.nature-cursor,html.nature-cursor body,html.nature-cursor a,html.nature-cursor button,html.nature-cursor summary{cursor:url("assets/sickle-cursor.png") 3 5,auto}html.nature-cursor input,html.nature-cursor textarea{cursor:text}html.nature-cursor select{cursor:pointer}html.nature-cursor input[type=range]{cursor:ew-resize}html.nature-cursor button:disabled{cursor:not-allowed}}`;document.head.append(style);
let enabled=true;try{enabled=localStorage.getItem('sts-nature-cursor')!=='off';}catch{}document.documentElement.classList.toggle('nature-cursor',enabled);
const header=document.querySelector('.header-actions');
if(header&&matchMedia('(hover:hover) and (pointer:fine)').matches){
 const b=document.createElement('button');b.type='button';b.className='cursor-control';b.append(icon('sickle'));
 const label=document.createElement('span');label.className='cursor-label';label.setAttribute('data-no-translate','');b.append(label);
 const feedback=document.createElement('div');feedback.className='cursor-feedback';feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');feedback.setAttribute('data-no-translate','');document.body.append(feedback);let feedbackTimer;
 const t=s=>window.STS_I18N?window.STS_I18N.t(s):s;
 function sync(){const status=enabled?'Sickle cursor on':'Sickle cursor off';b.setAttribute('aria-pressed',String(enabled));b.setAttribute('aria-label',t(status+'. '+(enabled?'Use standard pointer':'Use sickle pointer')));b.title=t(enabled?'Use standard pointer':'Use sickle pointer');label.textContent=t(status);}
 b.addEventListener('click',()=>{enabled=!enabled;document.documentElement.classList.toggle('nature-cursor',enabled);try{localStorage.setItem('sts-nature-cursor',enabled?'on':'off');}catch{}sync();feedback.textContent=t(enabled?'Sickle pointer enabled':'Standard pointer enabled');feedback.classList.add('show');clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>feedback.classList.remove('show'),2400);});
 document.addEventListener('sts-language-change',sync);sync();header.insertBefore(b,header.querySelector('#theme-toggle,#theme'));
}
})();
